  app.post('/api/v22/deals/:id/quality-review',async(req,res,next)=>{try{const u=manager(req,res);if(!u)return;const d=findDeal(data,req.params.id);if(!d)throw new Error('Negociación no encontrada.');const incoming=(d.messages||[]).filter(m=>m.direction==='incoming'),out=(d.messages||[]).filter(m=>m.direction==='outgoing'),sent=sentimentFromMessages(d.messages||[]);let score=70;if(out.length)score+=10;if(incoming.length&&out.length)score+=5;if(sent==='negative')score-=15;if((d.messages||[]).some(m=>/gracias|perfecto|excelente/i.test(m.text||'')))score+=5;score=Math.max(0,Math.min(100,score));const review={id:makeId('qrev22'),dealId:d.id,clientId:d.clientId,score,dimensions:{response:out.length?85:40,clarity:80,resolution:d.stage==='won'?95:d.stage==='lost'?55:75,protocol:80},notes:[sent==='negative'?'Revisar señales de insatisfacción y resolución.':'Tono general estable.',out.length?'Existe respuesta del equipo.':'No se detectó respuesta del equipo.'],reviewedByUserId:u.id,reviewedByName:u.name,createdAt:timestamp()};data.v22QualityReviews.unshift(review);audit(u,'v22_quality_review',{dealId:d.id,score},d.branchId);await store.save();res.json({review});}catch(e){next(e)}});

