  app.post('/api/v22/automations',async(req,res,next)=>{try{const u=manager(req,res);if(!u)return;const b=req.body||{},rule={id:makeId('auto22'),name:text(b.name||'Nueva automatización',180),trigger:text(b.trigger||'deal.updated',120),conditions:arr(b.conditions).slice(0,20),actions:arr(b.actions).slice(0,30),active:b.active!==false,stopOnError:b.stopOnError!==false,createdAt:timestamp(),updatedAt:timestamp(),createdByUserId:u.id,createdByName:u.name,runCount:0};data.v22Automations.unshift(rule);audit(u,'v22_automation_created',{ruleId:rule.id,name:rule.name});await store.save();res.json({rule});}catch(e){next(e)}});
  app.put('/api/v22/automations/:id',async(req,res,next)=>{try{const u=manager(req,res);if(!u)return;const r=data.v22Automations.find(x=>x.id===req.params.id);if(!r)throw new Error('Automatización no encontrada.');for(const k of ['name','trigger'])if(req.body?.[k]!==undefined)r[k]=text(req.body[k],k==='name'?180:120);if(Array.isArray(req.body?.conditions))r.conditions=req.body.conditions.slice(0,20);if(Array.isArray(req.body?.actions))r.actions=req.body.actions.slice(0,30);if(req.body?.active!==undefined)r.active=req.body.active!==false;r.updatedAt=timestamp();audit(u,'v22_automation_updated',{ruleId:r.id});await store.save();res.json({rule:r});}catch(e){next(e)}});
