  app.post('/api/v22/tickets',async(req,res,next)=>{try{const u=auth(req,res);if(!u)return;const t=createTicket({...req.body,branchId:req.body?.branchId||u.branchId||primaryBranchId()});audit(u,'v22_ticket_created',{ticketId:t.id},t.branchId);event('ticket.created',{ticketId:t.id,clientId:t.clientId,dealId:t.dealId},u);await store.save();res.json({ticket:{...t,sla:ticketSla(t)}});}catch(e){next(e)}});
  app.put('/api/v22/tickets/:id',async(req,res,next)=>{try{const u=auth(req,res);if(!u)return;const t=data.v22Tickets.find(x=>x.id===req.params.id);if(!t)throw new Error('Ticket no encontrado.');if(u.role==='agent'&&t.assignedUserId&&t.assignedUserId!==u.id)return res.status(403).json({error:'Sin permiso.'});for(const k of ['subject','description','category','resolution'])if(req.body?.[k]!==undefined)t[k]=text(req.body[k],k==='description'||k==='resolution'?5000:240);if(['low','normal','high','urgent'].includes(req.body?.priority))t.priority=req.body.priority;if(['open','working','waiting_customer','resolved','closed'].includes(req.body?.status)){t.status=req.body.status;if(t.status==='resolved'&&!t.resolvedAt)t.resolvedAt=timestamp();}if(req.body?.assignedUserId!==undefined){const a=(data.users||[]).find(x=>x.id===req.body.assignedUserId);t.assignedUserId=a?.id||null;t.assignedUserName=a?.name||'';}t.updatedAt=timestamp();audit(u,'v22_ticket_updated',{ticketId:t.id,status:t.status},t.branchId);event('ticket.updated',{ticketId:t.id,clientId:t.clientId,dealId:t.dealId,status:t.status},u);await store.save();res.json({ticket:{...t,sla:ticketSla(t)}});}catch(e){next(e)}});
