  app.post('/api/v22/quotes',async(req,res,next)=>{try{const u=auth(req,res);if(!u)return;const b=req.body||{},client=findClient(data,b.clientId);if(!client)throw new Error('Seleccioná un cliente.');const deal=b.dealId?findDeal(data,b.dealId):null;const q={id:makeId('quote22'),number:`P-${new Date().getFullYear()}-${String((data.v22Quotes||[]).length+1).padStart(5,'0')}`,clientId:client.id,dealId:deal?.id||null,branchId:deal?.branchId||u.branchId||primaryBranchId(),title:text(b.title||'Propuesta comercial',180),items:arr(b.items).map(i=>({id:makeId('qitem'),description:text(i.description,300),quantity:Math.max(.01,num(i.quantity,1)),unitPrice:Math.max(0,num(i.unitPrice,0))})).filter(i=>i.description),discountPercent:Math.max(0,Math.min(100,num(b.discountPercent))),taxPercent:Math.max(0,Math.min(100,num(b.taxPercent))),terms:text(b.terms,4000),validUntil:b.validUntil||null,status:'draft',publicToken:randomToken('quote'),version:1,createdByUserId:u.id,createdByName:u.name,createdAt:timestamp(),updatedAt:timestamp()};if(!q.items.length)throw new Error('Agregá al menos un ítem.');data.v22Quotes.unshift(q);audit(u,'v22_quote_created',{quoteId:q.id,number:q.number},q.branchId);event('quote.created',{quoteId:q.id,clientId:q.clientId,dealId:q.dealId},u);await store.save();res.json({quote:{...q,totals:quoteTotal(q.items,q.discountPercent,q.taxPercent)},publicUrl:`/portal/v22/quote/${q.publicToken}`});}catch(e){next(e)}});
